mapper.select:
select t.id, t.name, t.alias, t.url, t.status, t.create_time, t.create_by, t.update_time, t.update_by
from sys_tenant t
where t.del_flag = 0

    and t.name like concat('%', #{req.name}, '%')


    and t.alias like concat('%', #{req.alias}, '%')


    and t.status = #{req.status}


    and t.create_time >= #{req.startCreateTime}


    and t.create_time <= #{req.endCreateTime}

order by t.id
